#include <iostream>
#include <fstream>
#include <string>
using namespace std;

string kompresja(const string& s) {
    string wynik = "";
    int i = 0;
    while (i < (int)s.length()) {
        char c = s[i];
        int cnt = 0;
        while (i < (int)s.length() && s[i] == c) {
            cnt++;
            i++;
        }
        wynik += c;
        wynik += to_string(cnt);
    }
    return wynik;
}

string dekompresja(const string& s) {
    string wynik = "";
    int i = 0;
    while (i < (int)s.length()) {
        char c = s[i];
        i++;
        int num = 0;
        while (i < (int)s.length() && isdigit(s[i])) {
            num = num * 10 + (s[i] - '0');
            i++;
        }
        for (int j = 0; j < num; j++) {
            wynik += c;
        }
    }
    return wynik;
}

int main() {
    ifstream plik("dane.txt");
    char typ;
    string napis;
    string bestOryg, bestKomp;
    int bestRedukcja = -1;
    while (plik >> typ >> napis) {
        if (typ == 'K') {
            string wynik = kompresja(napis);
            cout << "K " << napis << " -> " << wynik
                 << " (" << napis.length() << " -> " << wynik.length() << ")" << endl;
            int redukcja = (int)napis.length() - (int)wynik.length();
            if (redukcja > bestRedukcja) {
                bestRedukcja = redukcja;
                bestOryg = napis;
                bestKomp = wynik;
            }
        } else {
            string wynik = dekompresja(napis);
            cout << "D " << napis << " -> " << wynik
                 << " (" << napis.length() << " -> " << wynik.length() << ")" << endl;
        }
    }
    cout << "Najlepsza kompresja: " << bestOryg << " -> " << bestKomp
         << " (redukcja " << bestRedukcja << ")" << endl;
    return 0;
}
```

**Wyjasnienie**: Kompresja grupuje identyczne sasiednie znaki i zapisuje jako para znak+ilosc. Dekompresja parsuje pary litera+liczba (wielocyfrowa) i powtarza litere. Porownujemy dlugosci wynikow kompresji, aby znalezc najlepsza redukcje.

Weryfikacja:
Kompresja:
- aaabbbccc: a*3,b*3,c*3 -> "a3b3c3" (9->6, redukcja 3)
- xxxyyyxxxy: x*3,y*3,x*3,y*1 -> "x3y3x3y1" (10->8, redukcja 2)
- aaaaabbbbb: a*5,b*5 -> "a5b5" (10->4, redukcja 6)
- abcabc: kazdy*1 -> "a1b1c1a1b1c1" (6->12, redukcja -6)

Dekompresja:
- a3b2c1: a*3=aaa, b*2=bb, c*1=c -> "aaabbc" (6 znakow wej., 6 wyj.)
- x10y2z1: x*10=xxxxxxxxxx, y*2=yy, z*1=z -> "xxxxxxxxxxyyz" (7 znakow wej., 13 wyj.)
- a1b1c1d1e1: a,b,c,d,e po 1 -> "abcde" (10 znakow wej., 5 wyj.)
- z3a12: z*3=zzz, a*12=aaaaaaaaaaaa -> "zzzaaaaaaaaaaaa" (5 znakow wej., 15 wyj.)

Najlepsza kompresja: redukcje to 3, 2, 6, -6. Max = 6 (aaaaabbbbb -> a5b5).
